add_action( 'admin_init', 'perfectpixel_featured_image_column_setup' );

function perfectpixel_featured_image_column_setup() {
	foreach ( get_post_types( array( 'show_ui' => true ) ) as $type ) {
		if ( 'product' === $type || ! post_type_supports( $type, 'thumbnail' ) ) {
			continue;
		}
		add_filter( "manage_{$type}_posts_columns", 'perfectpixel_featured_image_column' );
		add_action( "manage_{$type}_posts_custom_column", 'perfectpixel_featured_image_column_value', 10, 2 );
	}
}

function perfectpixel_featured_image_column( $columns ) {
	$new = array();
	foreach ( $columns as $key => $label ) {
		if ( 'title' === $key ) {
			$new['perfectpixel_thumb'] = '<span class="dashicons dashicons-format-image" title="Επιλεγμένη εικόνα"></span>';
		}
		$new[ $key ] = $label;
	}
	return $new;
}

function perfectpixel_featured_image_column_value( $column, $post_id ) {
	if ( 'perfectpixel_thumb' === $column ) {
		echo has_post_thumbnail( $post_id ) ? get_the_post_thumbnail( $post_id, array( 48, 48 ), array( 'style' => 'width:48px;height:48px;object-fit:cover;border-radius:3px' ) ) : '<span aria-hidden="true">&ndash;</span>';
	}
}
